"""Focused public conversation page for the persistent agent."""
from __future__ import annotations


def talk_agent_document() -> str:
    return r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Talk to Ferro · LivingRuntime</title><style>
:root{color-scheme:dark;--bg:#06100d;--panel:#091813;--panel2:#0d2119;--green:#70f3b2;--text:#edf7f1;--muted:#8da298;--line:rgba(112,243,178,.15);--soft:rgba(112,243,178,.08)}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,textarea{font:inherit}a{color:inherit}.app{min-height:100vh;display:grid;grid-template-rows:58px 1fr}.top{position:sticky;top:0;z-index:20;display:flex;align-items:center;justify-content:space-between;padding:0 22px;border-bottom:1px solid var(--line);background:rgba(6,16,13,.92);backdrop-filter:blur(14px)}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;font-weight:720}.brand-dot{width:9px;height:9px;border-radius:50%;background:var(--green);box-shadow:0 0 16px var(--green)}.top-right{display:flex;align-items:center;gap:14px;color:var(--muted);font-size:.78rem}.online{display:flex;align-items:center;gap:7px}.online i{width:7px;height:7px;border-radius:50%;background:var(--green)}.workspace{width:min(100%,980px);margin:0 auto;display:grid;grid-template-rows:auto 1fr auto;min-height:calc(100vh - 58px)}.intro{padding:30px 22px 12px}.eyebrow{font:700 .62rem ui-monospace,monospace;letter-spacing:.13em;color:var(--green)}.intro h1{margin:8px 0 7px;font:500 clamp(2rem,5vw,3.4rem)/1 Georgia,serif;letter-spacing:-.035em}.intro p{margin:0;max-width:700px;color:var(--muted);line-height:1.55;font-size:.86rem}.log{padding:14px 22px 24px;display:flex;flex-direction:column;gap:26px;min-height:360px}.turn{display:grid;grid-template-columns:34px minmax(0,1fr);gap:12px;align-items:start}.avatar{width:30px;height:30px;border-radius:9px;display:grid;place-items:center;font-weight:800;font-size:.72rem;border:1px solid var(--line);background:var(--panel2)}.assistant-body{min-width:0}.answer{font-size:.92rem;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere}.user-turn{display:flex;justify-content:flex-end}.user-bubble{max-width:min(78%,720px);padding:11px 14px;border-radius:18px 18px 5px 18px;background:#173329;line-height:1.55;font-size:.9rem;white-space:pre-wrap;overflow-wrap:anywhere}.thinking{margin:0 0 10px;border:1px solid var(--line);border-radius:12px;background:rgba(10,28,21,.7);overflow:hidden}.thinking summary{list-style:none;cursor:pointer;display:flex;align-items:center;gap:8px;padding:9px 11px;color:#b9cec2;font-size:.76rem;user-select:none}.thinking summary::-webkit-details-marker{display:none}.thinking summary:after{content:"⌄";margin-left:auto;color:#6f897b;transition:transform .18s}.thinking[open] summary:after{transform:rotate(180deg)}.spinner{width:11px;height:11px;border-radius:50%;border:1.5px solid rgba(112,243,178,.25);border-top-color:var(--green);animation:spin .8s linear infinite}.thinking.done .spinner{animation:none;border-color:var(--green);background:var(--green);box-shadow:inset 0 0 0 3px #0b1d16}.thinking.error .spinner{animation:none;border-color:#e7b783;background:#e7b783}.elapsed{color:#61796d;font:650 .62rem ui-monospace,monospace}.think-body{border-top:1px solid var(--line);padding:10px 12px 12px}.stage{color:#9cb3a7;font-size:.73rem;line-height:1.45;margin-bottom:8px}.reasoning-note{color:#60776b;font-size:.64rem;line-height:1.45;margin-bottom:8px}.reasoning-grid{display:grid;gap:7px}.reason-row{display:grid;grid-template-columns:94px 1fr;gap:8px;font-size:.7rem;line-height:1.45}.reason-row b{color:#799387;font-weight:650}.reason-row span{color:#afc3b8;white-space:pre-wrap;overflow-wrap:anywhere}.composer-wrap{position:sticky;bottom:0;padding:10px 18px 20px;background:linear-gradient(180deg,rgba(6,16,13,0),#06100d 24%)}.composer{border:1px solid rgba(112,243,178,.22);border-radius:18px;background:#0b1b15;box-shadow:0 18px 60px rgba(0,0,0,.25);padding:10px 10px 8px}.composer textarea{width:100%;min-height:44px;max-height:180px;resize:none;border:0;outline:0;background:transparent;color:var(--text);padding:8px 9px;line-height:1.45}.composer-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:0 3px}.hint{color:#5f766a;font-size:.64rem}.send{width:36px;height:36px;border:0;border-radius:11px;background:var(--green);color:#06100d;font-weight:900;cursor:pointer}.send:disabled{opacity:.45;cursor:wait}.statusline{min-height:18px;margin:5px 4px 0;color:#62796e;font-size:.62rem}.error-text{color:#e7b783}.welcome .answer{color:#b8cbc1}.chips{display:flex;gap:7px;flex-wrap:wrap;margin-top:13px}.chip{border:1px solid var(--line);border-radius:999px;padding:6px 9px;color:#789185;font:650 .58rem ui-monospace,monospace}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:680px){.top{padding:0 14px}.top-right a{display:none}.workspace{min-height:calc(100vh - 58px)}.intro{padding:22px 15px 8px}.intro h1{font-size:2rem}.log{padding:12px 14px 22px;gap:22px}.turn{grid-template-columns:29px minmax(0,1fr);gap:9px}.avatar{width:27px;height:27px}.user-bubble{max-width:88%}.reason-row{grid-template-columns:78px 1fr}.composer-wrap{padding:9px 10px 12px}.hint{display:none}}
</style></head><body><div class="app"><header class="top"><a class="brand" href="/agents/ferro/"><i class="brand-dot"></i><span id="brand">Ferro</span></a><div class="top-right"><span class="online"><i></i><span id="runtime-status">Live</span></span><a href="/live/">Live state</a></div></header><main class="workspace"><section class="intro"><div class="eyebrow">PUBLIC CONVERSATION · PERSISTENT AGENT</div><h1 id="title">Talk to Ferro</h1><p id="intro">A live conversation with Ferro. Replies stream as they are generated, and each turn can show a safe public reasoning summary from current runtime state.</p><div class="chips"><span class="chip">OPEN CONVERSATION</span><span class="chip">LIVE RESPONSE STATUS</span><span class="chip">PUBLIC REASONING SUMMARY</span></div></section><section class="log" id="log"><div class="turn welcome"><div class="avatar">F</div><div class="assistant-body"><div class="answer">You can talk to me normally. When you send a message, you’ll see when I receive it, what public state I’m grounding on, and when I start composing the answer.</div></div></div></section><section class="composer-wrap"><div class="composer"><textarea id="input" maxlength="1000" rows="1" placeholder="Message Ferro"></textarea><div class="composer-row"><span class="hint">Enter to send · Shift+Enter for a new line</span><button class="send" id="send" type="button" aria-label="Send">↑</button></div><div class="statusline" id="send-status" aria-live="polite"></div></div></section></main></div><script>(()=>{const $=id=>document.getElementById(id);let sending=false;let visitorId=localStorage.getItem('ferro_public_visitor_id');if(!/^v_[a-f0-9]{24,64}$/.test(visitorId||'')){const b=new Uint8Array(16);crypto.getRandomValues(b);visitorId='v_'+Array.from(b,x=>x.toString(16).padStart(2,'0')).join('');localStorage.setItem('ferro_public_visitor_id',visitorId)}const esc=v=>String(v??'');const set=(id,v,f='—')=>{$(id).textContent=(v===undefined||v===null||v==='')?f:String(v)};function scrollEnd(){$('log').lastElementChild?.scrollIntoView({behavior:'smooth',block:'end'})}function addUser(text){const row=document.createElement('div');row.className='user-turn';const bubble=document.createElement('div');bubble.className='user-bubble';bubble.textContent=text;row.append(bubble);$('log').append(row);scrollEnd()}function addAssistantPending(){const turn=document.createElement('div');turn.className='turn';turn.innerHTML='<div class="avatar">F</div><div class="assistant-body"><details class="thinking" open><summary><i class="spinner"></i><span class="think-label">Ferro is thinking</span><span class="elapsed">0.0s</span></summary><div class="think-body"><div class="stage">Message received. Reading current state…</div><div class="reasoning-note">This panel shows a bounded public decision summary, not hidden chain-of-thought.</div><div class="reasoning-grid"></div></div></details><div class="answer"></div></div>';$('log').append(turn);scrollEnd();return{turn,details:turn.querySelector('.thinking'),label:turn.querySelector('.think-label'),elapsed:turn.querySelector('.elapsed'),stage:turn.querySelector('.stage'),grid:turn.querySelector('.reasoning-grid'),answer:turn.querySelector('.answer')}}function renderReasoning(ui,d){const rows=[['Focus',d.headline],['Goal',d.goal],['Evidence',d.evidence],['Judgment',d.decision],['Uncertainty',d.uncertainty],['Next',d.next_action]].filter(x=>x[1]);ui.grid.replaceChildren(...rows.map(([k,v])=>{const r=document.createElement('div');r.className='reason-row';const b=document.createElement('b');b.textContent=k;const s=document.createElement('span');s.textContent=esc(v);r.append(b,s);return r}))}function parseEvent(block){let event='message',data='';for(const line of block.replace(/\r/g,'').split('\n')){if(line.startsWith('event:'))event=line.slice(6).trim();else if(line.startsWith('data:'))data+=line.slice(5).trim()}if(!data)return null;try{return{event,data:JSON.parse(data)}}catch{return null}}async function refreshState(){try{const r=await fetch('/api/agent/status',{cache:'no-store'});if(!r.ok)return;const d=await r.json(),p=d.persona||{},a=d.agent||{};set('brand',p.name||'Ferro');set('title','Talk to '+(p.name||'Ferro'));set('runtime-status',a.online?'Live':'Stale')}catch{set('runtime-status','Offline')}}async function sendMessage(){if(sending)return;const input=$('input'),message=input.value.trim();if(!message){input.focus();return}sending=true;$('send').disabled=true;input.value='';input.style.height='auto';addUser(message);const ui=addAssistantPending();const started=performance.now();const timer=setInterval(()=>{ui.elapsed.textContent=((performance.now()-started)/1000).toFixed(1)+'s'},100);set('send-status','Ferro received your message.','');try{const response=await fetch('/api/agent/chat/stream',{method:'POST',headers:{'content-type':'application/json','accept':'text/event-stream'},body:JSON.stringify({message,visitor_id:visitorId})});if(!response.ok){let d={};try{d=await response.json()}catch{}throw new Error(d.error||('HTTP '+response.status))}if(!response.body)throw new Error('stream_unavailable');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',done=false;while(!done){const part=await reader.read();done=part.done;buffer+=decoder.decode(part.value||new Uint8Array(),{stream:!done});buffer=buffer.replace(/\r\n/g,'\n');let cut;while((cut=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,cut);buffer=buffer.slice(cut+2);const evt=parseEvent(block);if(!evt)continue;const d=evt.data;if(evt.event==='status'){ui.label.textContent=d.label||'Ferro is thinking';ui.stage.textContent=d.detail||d.label||'';set('send-status',d.label||'Ferro is thinking…','')}else if(evt.event==='reasoning'){renderReasoning(ui,d)}else if(evt.event==='delta'){ui.answer.textContent+=esc(d.text);scrollEnd()}else if(evt.event==='done'){ui.details.classList.add('done');ui.label.textContent='Public reasoning summary';ui.stage.textContent='Reply completed.';ui.details.open=false;set('send-status','Reply complete.','');refreshState()}else if(evt.event==='error'){throw new Error(d.error||'chat_model_temporarily_unavailable')}}}}if(!ui.answer.textContent.trim())throw new Error('empty_reply')}catch(err){ui.details.classList.add('error');ui.label.textContent='Reply interrupted';ui.stage.textContent='The model did not finish this turn. You can retry.';ui.answer.classList.add('error-text');ui.answer.textContent='Chat unavailable: '+(err&&err.message?err.message:'connection error');set('send-status','Reply failed. Please try again.','')}finally{clearInterval(timer);ui.elapsed.textContent=((performance.now()-started)/1000).toFixed(1)+'s';sending=false;$('send').disabled=false;input.focus();scrollEnd()}}$('send').addEventListener('click',sendMessage);$('input').addEventListener('input',e=>{e.target.style.height='auto';e.target.style.height=Math.min(e.target.scrollHeight,180)+'px'});$('input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage()}});refreshState();setInterval(refreshState,5000)})();</script></body></html>'''


__all__ = ["talk_agent_document"]
